// JavaScript port of the move-forward plan screen in screen_rules.json, for an artifact page or a
// Deno function. The Python reference is tamarket/moveon.py (screen_plan); this port must pass
// screen_cases.json, and tests/test_spec_js.py checks it with node when node is installed.
//
// spec = { rules: screen_rules.json, schema: moveon.schema.json, pathways: pathways.json,
//          fdcore: fdcore_patterns.json (generated by scripts/export_fdcore_patterns.py) }
// The household record must carry eligible_pathways (the caseload file does): the page shows
// Python's pathway suggestions and never works them out itself.
// options.deny: deny-list lines. Never ship them to a page; a server-side function passes them.
// options.review: the usable reviewer notes the plan was drafted against (usableNotes), if any.
//
// Suggestions for an officer to approve, never decisions. A net, not a guarantee.

const re = (p, flags = "") => new RegExp(typeof p === "string" ? p : p.pattern, "g" + (typeof p === "string" ? flags : (p.flags || "")));
const first = (rx, s) => { rx.lastIndex = 0; const m = rx.exec(s); rx.lastIndex = 0; return m; };
const all = (rx, s) => { rx.lastIndex = 0; const out = []; let m; while ((m = rx.exec(s)) !== null) { out.push(m); if (m[0] === "") rx.lastIndex++; } rx.lastIndex = 0; return out; };
const escapeRx = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
const isNum = (v) => typeof v === "number" && Number.isFinite(v);

function compile(rules) {
  const d = rules.decision, p = rules.person, f = rules.figure;
  const words = Object.keys(f.number_words).sort((a, b) => b.length - a.length);
  return {
    refs: rules.references.patterns.map((x) => re(x, rules.references.flags)),
    sentence: re(d.sentence_split), clause: re(d.clause_split), opener: re(d.conditional_opener),
    strong: re(d.strong_hedge), softHedge: re(d.soft_hedge),
    hard: d.hard.map((x) => re(x, d.flags)), soft: d.soft.map((x) => re(x, d.flags)),
    never: d.never_hedged.map((x) => re(x, d.flags)),
    honorific: re(p.honorific), capitalised: re(p.capitalised_word), acronym: re(p.acronym),
    number: re(f.number), numberWord: re("\\b(?:" + words.join("|") + ")\\b", "i"),
    disallowed: re(rules.style.disallowed_chars),
    instruction: re(rules.review.instruction), noteId: new RegExp(rules.review.note_id.pattern, rules.review.note_id.flags || ""),
  };
}

export function normaliseText(s, rules) {
  for (const [a, b] of rules.normalise.replace) s = s.split(a).join(b);
  return s;
}

function normalise(v, rules) {
  if (typeof v === "string") return normaliseText(v, rules);
  if (Array.isArray(v)) return v.map((x) => normalise(x, rules));
  if (v && typeof v === "object") { const o = {}; for (const [k, x] of Object.entries(v)) o[k] = normalise(x, rules); return o; }
  return v;
}

function textFields(v, skip, path = "", key = null, out = []) {
  if (typeof v === "string") { if (!skip.has(key)) out.push([path, v]); }
  else if (Array.isArray(v)) v.forEach((x, i) => textFields(x, skip, `${path}[${i}]`, key, out));
  else if (v && typeof v === "object") for (const [k, x] of Object.entries(v)) textFields(x, skip, path ? `${path}.${k}` : k, k, out);
  return out;
}

// --- schema (the subset of JSON Schema 2020-12 that moveon.schema.json uses) ---------------
const same = (a, b) => (typeof a === "boolean" || typeof b === "boolean") ? a === b : (a === b);
const sameJson = (a, b) => same(a, b) || (typeof a === "object" && typeof b === "object" && JSON.stringify(a) === JSON.stringify(b));
const typeOk = (v, t) => ({ object: v !== null && typeof v === "object" && !Array.isArray(v), array: Array.isArray(v),
  string: typeof v === "string", boolean: typeof v === "boolean", null: v === null, number: isNum(v),
  integer: isNum(v) && Number.isInteger(v) })[t];

export function validateSchema(value, schema, root = schema, path = "") {
  if (schema.$ref) return validateSchema(value, root.$defs[schema.$ref.replace("#/$defs/", "")], root, path);
  const errs = [], where = path || "(plan)";
  if ("const" in schema && !sameJson(value, schema.const)) errs.push([where, "must be " + JSON.stringify(schema.const)]);
  if (schema.enum && !schema.enum.some((e) => sameJson(value, e))) errs.push([where, "must be one of " + schema.enum.map((e) => JSON.stringify(e)).join(", ")]);
  if (schema.type && !typeOk(value, schema.type)) return errs.concat([[where, "must be of type " + schema.type]]);
  if (typeOk(value, "object")) {
    for (const k of schema.required || []) if (!(k in value)) errs.push([where, "missing " + k]);
    const props = schema.properties || {};
    for (const [k, v] of Object.entries(value)) {
      if (k in props) errs.push(...validateSchema(v, props[k], root, path ? `${path}.${k}` : k));
      else if (schema.additionalProperties === false) errs.push([where, "unexpected field " + k]);
    }
  }
  if (Array.isArray(value)) {
    if ("minItems" in schema && value.length < schema.minItems) errs.push([where, `needs at least ${schema.minItems} items`]);
    if ("maxItems" in schema && value.length > schema.maxItems) errs.push([where, `takes at most ${schema.maxItems} items`]);
    if (schema.items) value.forEach((v, i) => errs.push(...validateSchema(v, schema.items, root, `${path}[${i}]`)));
  }
  if (typeof value === "string") {
    const n = [...value].length;   // code points, as JSON Schema counts them
    if ("minLength" in schema && n < schema.minLength) errs.push([where, `needs at least ${schema.minLength} characters`]);
    if ("maxLength" in schema && n > schema.maxLength) errs.push([where, `takes at most ${schema.maxLength} characters`]);
    if (schema.pattern && !new RegExp(schema.pattern).test(value)) errs.push([where, "must match " + schema.pattern]);
  }
  return errs;
}

// --- fd-core guardrails (from fdcore_patterns.json) ---------------------------------------
export function fdcoreScan(text, fd, deny = []) {
  const P = fd.patterns, out = [];
  const company = re(P.company), email = re(P.email), phone = re(P.phone), postcode = re(P.postcode),
    accusing = re(P.accusing), brk = re(P.clause_break);
  const denyRx = deny.map((d) => d.trim()).filter((d) => d && !d.startsWith("#")).map((d) => re(escapeRx(d), "i"));
  const insideNumber = (line, start, end) => {
    const before = start > 0 ? line[start - 1] : "", after = line.slice(end, end + 2);
    return before === "." || /[0-9A-Za-z]/.test(before) || (after.slice(0, 1) === "." && /\d/.test(after.slice(1, 2))) || ["e", "E"].includes(after.slice(0, 1));
  };
  const hedged = (line, start, end) => {
    let lo = Math.max(0, start - fd.hedge_before);
    const before = all(brk, line.slice(lo, start));
    if (before.length) { const b = before[before.length - 1]; lo = lo + b.index + b[0].length; }
    let hi = Math.min(line.length, end + fd.hedge_after);
    const nxt = first(brk, line.slice(end, hi));
    if (nxt) hi = end + nxt.index;
    const window = line.slice(lo, hi).toLowerCase();
    return fd.hedges.some((h) => window.includes(h));
  };
  for (const line of text.split(/\r\n|\r|\n/)) {
    for (const m of all(company, line)) out.push({ kind: fd.kinds.company, text: m[0] });
    for (const m of all(email, line)) if (!fd.email_allow.includes(m[0].toLowerCase())) out.push({ kind: fd.kinds.email, text: m[0] });
    for (const m of all(postcode, line)) { if (m.index > 0 && line[m.index - 1] === "#") continue; out.push({ kind: fd.kinds.postcode, text: m[0] }); }
    for (const m of all(phone, line)) {
      const digits = m[0].replace(/\D/g, "");
      if (digits.length >= 10 && !/^(19|20)\d{2}/.test(digits) && !insideNumber(line, m.index, m.index + m[0].length)) out.push({ kind: fd.kinds.phone, text: m[0].trim() });
    }
    for (const rx of denyRx) for (const m of all(rx, line)) out.push({ kind: fd.kinds.deny, text: m[0] });
    for (const m of all(accusing, line)) if (!hedged(line, m.index, m.index + m[0].length)) out.push({ kind: fd.kinds.accusing, text: m[0] });
  }
  return out;
}

// --- decision, person, figure ----------------------------------------------------------------
export function stripReferences(text, rules, c = compile(rules)) {
  for (const rx of c.refs) { rx.lastIndex = 0; text = text.replace(rx, rules.references.replacement); }
  return text;
}

export function decisionFindings(text, rules, c = compile(rules)) {
  const out = [];
  for (const sentence of stripReferences(text, rules, c).split(c.sentence)) {
    for (const rx of c.never) for (const m of all(rx, sentence)) out.push(m[0]);
    if (first(c.opener, sentence)) continue;
    if (!first(c.softHedge, sentence)) for (const rx of c.soft) for (const m of all(rx, sentence)) out.push(m[0]);
    for (const clause of sentence.split(c.clause)) {
      if (!first(c.strong, clause)) for (const rx of c.hard) for (const m of all(rx, clause)) out.push(m[0]);
    }
  }
  return out;
}

export function personFindings(text, rules, recordId = "", c = compile(rules)) {
  const p = rules.person;
  let t = stripReferences(text, rules, c);
  if (recordId) t = t.split(recordId).join(" ");
  const allowed = new Set(p.allowed_words), acronyms = new Set(p.allowed_acronyms);
  const start = (i) => { let j = i - 1; while (j >= 0 && p.skip_back.includes(t[j])) j--; return j < 0 || p.starts.includes(t[j]); };
  const out = all(c.honorific, t).map((m) => m[0]);
  for (const m of all(c.capitalised, t)) {
    let w = m[0];
    for (const e of p.word_endings_removed) if (w.endsWith(e)) w = w.slice(0, w.length - e.length);
    if (allowed.has(w) || start(m.index)) continue;
    out.push(w);
  }
  for (const m of all(c.acronym, t)) if (!acronyms.has(m[0])) out.push(m[0]);
  return out;
}

export function recordFigures(record, rules, c = compile(rules)) {
  const ignored = new Set(rules.figure.record_keys_ignored), out = new Set();
  const walk = (v, key) => {
    if (ignored.has(key) || typeof v === "boolean" || v === null || v === undefined) return;
    if (typeof v === "number") out.add(v);
    else if (typeof v === "string") for (const m of all(c.number, v)) out.add(parseFloat(m[0].replace(/,/g, "")));
    else if (Array.isArray(v)) v.forEach((x) => walk(x, key));
    else if (typeof v === "object") for (const [k, x] of Object.entries(v)) walk(x, k);
  };
  walk(record, null);
  return out;
}

export function figureFindings(text, record, rules, statutory, c = compile(rules)) {
  let t = record.id ? text.split(record.id).join(" ") : text;
  const phrases = [...new Set(statutory.flatMap((s) => [s.text, ...(s.aliases || [])]))].sort((a, b) => b.length - a.length);
  for (const ph of phrases) t = t.replace(re("\\b" + escapeRx(ph) + "\\b", "i"), " ");
  t = stripReferences(t, rules, c);
  const allowed = recordFigures(record, rules, c), words = rules.figure.number_words;
  const out = all(c.number, t).filter((m) => !allowed.has(parseFloat(m[0].replace(/,/g, "")))).map((m) => m[0]);
  for (const m of all(c.numberWord, t)) if (!allowed.has(words[m[0].toLowerCase()])) out.push(m[0]);
  return out;
}

// --- reviewer notes (screen_rules.json, review) ---------------------------------------------
// The notes as given, checked for shape. Throws on a fault in the caller, never on a draft.
export function checkReview(review, rules) {
  const R = rules.review, noteId = new RegExp(R.note_id.pattern, R.note_id.flags || "");
  const notes = Array.isArray(review) ? review : review === undefined || review === null ? [] : null;
  if (notes === null) throw new Error("reviewer notes must be a list");
  if (notes.length > R.max_notes) throw new Error(`at most ${R.max_notes} reviewer notes`);
  const ids = notes.map((n) => (n && typeof n === "object" ? n.id : undefined));
  if (ids.some((i) => typeof i !== "string" || !noteId.test(i)) || new Set(ids).size !== ids.length) throw new Error("reviewer notes need unique ids review-1 to review-5");
  if (notes.some((n) => typeof n.text !== "string" || !["returned", "rejected"].includes(n.kind))) throw new Error("every reviewer note needs a text and a kind, returned or rejected");
  return notes;
}

// The note checks on one note, normalised and trimmed: style, fd-core, person, instruction, length.
export function noteFindings(text, household, spec, options = {}) {
  const rules = spec.rules, c = compile(rules), out = [];
  const add = (rule, detail) => out.push({ path: "note", rule, detail });
  const t = normaliseText(String(text), rules).trim();
  if (t.includes(rules.style.em_dash)) add("style", "em dash");
  for (const m of all(c.disallowed, t.split(rules.style.em_dash).join(""))) add("style", "character outside ASCII: " + m[0]);
  for (const f of fdcoreScan(t, spec.fdcore, options.deny || [])) add(rules.fdcore.rule_prefix + f.kind, f.text);
  const rid = household && typeof household === "object" ? String(household.id || "") : "";
  for (const n of personFindings(t, rules, rid, c)) add("person", n);
  for (const line of t.split("\n")) { const m = first(c.instruction, line); if (m) { add("instruction", m[0].slice(0, 80)); break; } }
  if ([...t].length > rules.review.max_note_length) add("length", String([...t].length));
  return out;
}

// {usable, held}: the notes that pass the note checks, text normalised and trimmed, and the rest.
export function usableNotes(review, household, spec, options = {}) {
  const usable = [], held = [];
  for (const n of checkReview(review, spec.rules)) {
    const problems = noteFindings(n.text, household, spec, options);
    const item = { id: n.id, kind: n.kind, text: normaliseText(n.text, spec.rules).trim() };
    if (problems.length) held.push(Object.assign(item, { problems })); else usable.push(item);
  }
  return { usable, held };
}

// The answers rule: one answer to each note given, none to any other, none still the placeholder.
export function reviewProblems(plan, notes, rules, c = compile(rules)) {
  const R = rules.review, out = [], add = (path, detail) => out.push({ path, rule: R.rule, detail });
  const given = notes.map((n) => n.id), seen = new Set();
  const answers = plan && typeof plan === "object" && !Array.isArray(plan) && Array.isArray(plan.responds_to_review) ? plan.responds_to_review : [];
  answers.forEach((a, i) => {
    const nid = a && typeof a === "object" ? a.note : undefined;
    if (typeof nid !== "string") return;
    const shown = c.noteId.test(nid) ? nid : "an unknown note";
    if (!given.includes(nid)) { add(`responds_to_review[${i}].note`, `${shown} is not one of the notes given`); return; }
    if (seen.has(nid)) add(`responds_to_review[${i}].note`, `${shown} is answered more than once`);
    seen.add(nid);
    if (typeof a.change === "string" && normaliseText(a.change, rules).trim() === R.placeholder) add(`responds_to_review[${i}].change`, `the answer to ${shown} is still the placeholder`);
  });
  const missing = given.filter((id) => !seen.has(id));
  if (missing.length) add("responds_to_review", `${missing.join(", ")} ${missing.length === 1 ? "has" : "have"} no answer`);
  return out;
}

// --- the screen --------------------------------------------------------------------------
export function screenPlan(plan, household, spec, options = {}) {
  const rules = spec.rules, c = compile(rules), problems = [];
  const add = (path, rule, detail) => problems.push({ path, rule, detail });
  const notes = checkReview(options.review, rules);
  plan = normalise(plan, rules);
  const fields = plan && typeof plan === "object" ? textFields(plan, new Set(rules.skip_keys)) : [];
  for (const [path, text] of fields) {
    if (text.includes(rules.style.em_dash)) add(path, "style", "em dash");
    for (const m of all(c.disallowed, text.split(rules.style.em_dash).join(""))) add(path, "style", "character outside ASCII: " + m[0]);
  }
  for (const [path, msg] of validateSchema(plan, spec.schema)) add(path, "schema", msg);
  const isObj = (v) => v !== null && typeof v === "object" && !Array.isArray(v);
  const synthetic = isObj(household) && household.synthetic === true;
  if (!synthetic) add("household", "record", "plans are drafted on synthetic records only");
  if (isObj(plan) && isObj(household) && plan.household_id !== household.id) add("household_id", "record", "does not match the record's id");
  if (synthetic && isObj(plan)) {
    if (!Array.isArray(household.eligible_pathways)) throw new Error("the record must carry eligible_pathways from tamarket/moveon.py");
    const eligible = new Set(household.eligible_pathways.map((p) => p.pathway_id));
    const known = new Set(spec.schema.$defs.pathway_id.enum), extra = rules.pathway.check_values;
    (Array.isArray(plan.pathway_suggestions) ? plan.pathway_suggestions : []).forEach((s, i) => {
      const pid = isObj(s) ? s.pathway_id : undefined;
      if (known.has(pid) && !eligible.has(pid)) add(`pathway_suggestions[${i}].pathway_id`, "pathway", `${pid} is not listed for this record`);
    });
    (Array.isArray(plan.officer_checks) ? plan.officer_checks : []).forEach((s, i) => {
      const pid = isObj(s) ? s.pathway_id : undefined;
      if ((known.has(pid) || extra.includes(pid)) && !(eligible.has(pid) || extra.includes(pid))) add(`officer_checks[${i}].pathway_id`, "pathway", `${pid} is not listed for this record`);
    });
  }
  const record = isObj(household) ? household : {}, statutory = spec.pathways.statutory_figures;
  for (const [path, text] of fields) {
    for (const f of fdcoreScan(text, spec.fdcore, options.deny || [])) add(path, rules.fdcore.rule_prefix + f.kind, f.text);
    for (const d of decisionFindings(text, rules, c)) add(path, "decision", d);
    for (const n of personFindings(text, rules, String(record.id || ""), c)) add(path, "person", n);
    for (const n of figureFindings(text, record, rules, statutory, c)) add(path, "figure", n);
  }
  problems.push(...reviewProblems(plan, notes, rules, c));
  return { passed: problems.length === 0, problems, plan };
}
